  "command": "cd /mnt/session/uploads && python3 - <<'EOF'
import json,collections
per=collections.Counter(); batch=collections.Counter(); first=None
for line in open('app.log'):
    try: d=json.loads(line)
    except: continue
    if d.get('service')!='checkout' or 'order_items' not in d.get('msg',''): continue
    m=d['msg']; minute=d['ts'][:16]
    if 'order_id = ?' in m: per[minute]+=1; first=first or d['ts']
    elif 'IN (?)' in m: batch[minute]+=1
print('first per-row query:', first)
for k in sorted(set(per)|set(batch)): print(k,'per-row',per[k],'batch',batch[k])
EOF
